"""Generate lab/data.js: precomputed topology signatures for the 128 patterns."""
from __future__ import annotations

import json
from pathlib import Path

from .layouts import seven_seg
from .topology import signature


def main() -> None:
    layout = seven_seg()
    data = {}
    for p in range(layout.n_patterns):
        s = signature(layout, p)
        data[str(p)] = [s.components, s.holes]
    out = Path(__file__).resolve().parents[1] / "lab" / "data.js"
    out.write_text(
        "// generated by foundation/build_lab_data.py\n"
        "globalThis.COV_TOPOLOGY = " + json.dumps(data, separators=(",", ":")) + ";\n",
        encoding="utf-8",
    )
    print("wrote", out)


if __name__ == "__main__":
    main()
